'use strict';
const nearbyHelpers=[{id:'minhanh',name:'Minh Anh',initials:'MA',age:22,range:'0,8 km',color:'orange',rating:'4,9',sessions:86,skills:['Zalo','Gọi video','Cỡ chữ'],bio:'Sinh viên năm cuối ngành Công nghệ thông tin. Cháu chỉ chậm, từng bước một, và để bác tự bấm trên máy của mình cho nhớ lâu.'},{id:'tuananh',name:'Tuấn Anh',initials:'TA',age:24,range:'1,2 km',color:'blue',rating:'4,8',sessions:41,skills:['Gửi ảnh','Android','Wi-Fi'],bio:'Kỹ sư phần mềm, rảnh các buổi chiều cuối tuần. Rành điện thoại Android, cài Wi-Fi và chuyển ảnh sang máy tính.'}];
let livePosition=null,locating=false;
const sessionPrice=99000;
function mapsURL(place,directions=false){const u=new URL(directions?'https://www.google.com/maps/dir/':'https://www.google.com/maps/search/');u.searchParams.set('api','1');u.searchParams.set(directions?'destination':'query',place);if(directions)u.searchParams.set('travelmode','walking');return u.href}
function miniMap(){return `<div class="local-map" role="img" aria-label="Bản đồ người hướng dẫn quanh khu vực của bác"><div class="map-park park-one"></div><div class="map-park park-two"></div><div class="map-road road-one"></div><div class="map-road road-two"></div><div class="map-road road-three"></div><span class="map-place-label">Nhà văn hóa</span><span class="map-me">Bác</span><span class="map-helper helper-one">MA</span><span class="map-helper helper-two">TA</span></div>`}
function nearby(){if(state.role!=='senior')return supportRequests();return `<button class="back-btn" data-screen="home">${icon('back')} Trang chủ</button><h1 class="screen-title">Nhờ người chỉ tận tay</h1><p class="screen-subtitle">Hẹn một bạn trẻ ở gần, ngồi cùng bác ở nhà văn hóa hay quán cà phê và chỉ từng bước.</p><div class="service-price">${icon('calendar')}<span><strong>99.000đ / buổi 45 phút</strong><small>Thanh toán sau khi học xong</small></span></div><h2 class="section-label">Bác cần giúp việc gì?</h2><div class="service-issues">${['Gọi video','Gửi ảnh','Chữ khó đọc','Việc khác'].map(issue=>`<button class="chip ${state.supportIssue===issue?'active':''}" data-support-issue="${issue}">${issue}</button>`).join('')}</div><h2 class="section-label">Gặp ở đâu?</h2><button class="secondary wide" data-action="locate-support" ${locating?'disabled':''}>${icon('locate')} ${locating?'Đang xác định vị trí…':'Dùng vị trí hiện tại'}</button><p class="subtle-note">${livePosition?'Đã xác định vị trí của bác. Vị trí chỉ dùng để gợi ý người ở gần, chưa chia sẻ cho ai.':'Hoặc nhập một địa điểm công cộng quen thuộc bên dưới.'}</p><label class="field-label" for="support-area">Điểm hẹn</label><input class="form-control" id="support-area" maxlength="160" value="${esc(state.supportLandmark||'Hồ Hoàn Kiếm, Hà Nội')}" placeholder="Ví dụ: nhà văn hóa phường, thư viện, quán cà phê"><a class="maps-link" href="${esc(mapsURL(state.supportLandmark||'Hồ Hoàn Kiếm, Hà Nội'))}" id="support-map-link" target="_blank" rel="noopener">${icon('map')} Xem trên Google Maps ${icon('external')}</a>${livePosition?`<a class="maps-link" href="${esc(mapsURL(livePosition.latitude+','+livePosition.longitude))}" target="_blank" rel="noopener">${icon('pin')} Xem vị trí của bác trên Google Maps ${icon('external')}</a>`:''}${miniMap()}<h2 class="section-label">Người hướng dẫn gần bác</h2>${nearbyHelpers.map(h=>`<article class="friend-card">${person(h.name,h.initials,`${h.age} tuổi · cách ${h.range} · ★ ${h.rating}`,h.color)}<div class="interest-tags">${h.skills.map(s=>`<span class="tag">${s}</span>`).join('')}</div><button class="secondary wide" data-support-helper="${h.id}">Xem hồ sơ ${icon('chevron')}</button></article>`).join('')}${state.support?'<button class="primary wide" data-screen="appointment">Xem lịch hẹn của bác</button>':''}<p class="subtle-note">Các bạn hướng dẫn cách dùng điện thoại; không sửa máy và không thao tác ngân hàng thay bác.</p>`}
function helperProfile(){if(state.role!=='senior')return denied();const h=nearbyHelpers.find(h=>h.id===state.helperId)||nearbyHelpers[0];return `<button class="back-btn" data-screen="nearby">${icon('back')} Người hướng dẫn gần bác</button><div class="profile-hero">${avatar(h.initials,h.color,h.name)}<div><h1 class="screen-title">${h.name}</h1><p>${h.age} tuổi · cách bác ${h.range}</p></div></div><span class="tag">${icon('badge')} Đã xác thực · Đã qua tập huấn</span><div class="helper-stats"><div><strong>★ ${h.rating}</strong><span>đánh giá</span></div><div><strong>${h.sessions}</strong><span>buổi đã dạy</span></div><div><strong>${h.range}</strong><span>từ chỗ bác</span></div></div><p class="question-body">${h.bio}</p><form id="support-booking-form"><div class="service-price">${icon('calendar')}<span><strong>99.000đ / buổi 45 phút</strong><small>Thanh toán sau khi học xong</small></span></div><label class="field-label" for="booking-issue">Bác muốn được chỉ việc gì?</label><select class="form-control" id="booking-issue" name="issue">${['Gọi video','Gửi ảnh','Chữ khó đọc','Việc khác'].map(i=>`<option ${i===state.supportIssue?'selected':''}>${i}</option>`).join('')}</select><label class="field-label" for="booking-place">Điểm hẹn</label><input class="form-control" id="booking-place" name="place" required minlength="5" maxlength="160" value="${esc(state.supportLandmark||'Hồ Hoàn Kiếm, Hà Nội')}"><label class="field-label" for="booking-slot">Thời gian</label><select class="form-control" id="booking-slot" name="slot"><option>Sáng mai · 09:00–09:45</option><option>Chiều mai · 14:00–14:45</option><option>Chiều mai · 16:00–16:45</option></select><label class="consent-label"><input type="checkbox" name="consent" required> <span>Tôi đồng ý chia sẻ việc cần giúp và điểm hẹn với ${h.name}.</span></label><div class="safe-note">${icon('shield')} Bác luôn tự cầm máy và tự bấm. Không đưa mật khẩu, mã OTP hay giao điện thoại cho người khác mang đi.</div><button class="primary wide" type="submit">Gửi yêu cầu cho ${h.name} ${icon('arrow')}</button><p class="subtle-note">${h.name} thường xác nhận trong vòng 1 giờ.</p></form>`}
function appointment(){if(state.role!=='senior')return supportRequests();const b=state.support;if(!b)return `<h1 class="screen-title">Bác chưa có lịch hẹn nào</h1><p class="screen-subtitle">Chọn một người hướng dẫn gần nhà để bắt đầu nhé.</p><button class="primary wide" data-screen="nearby">Tìm người hướng dẫn</button>`;const h=nearbyHelpers.find(h=>h.id===b.helperId)||nearbyHelpers[0];const labels={pending:'Đang chờ xác nhận',accepted:'Đã xác nhận',finished:'Đã hoàn thành',cancelled:'Đã hủy'};return `<button class="back-btn" data-screen="nearby">${icon('back')} Nhờ người chỉ tận tay</button><h1 class="screen-title">Lịch hẹn của bác</h1><span class="tag status-tag ${b.status==='pending'?'orange':''}">${labels[b.status]||labels.pending}</span>${person(h.name,h.initials,`Người hướng dẫn · ★ ${h.rating}`,h.color)}<div class="community-post summary-card"><div class="stat-row"><span>Việc cần giúp</span><strong>${esc(b.issue)}</strong></div><div class="stat-row"><span>Thời gian</span><strong class="wrap-value">${esc(b.slot)}</strong></div><div class="stat-row"><span>Điểm hẹn</span><strong class="wrap-value">${esc(b.place)}</strong></div><div class="stat-row"><span>Chi phí</span><strong>${vnd(b.price)}</strong></div></div><a class="maps-link" href="${esc(mapsURL(b.place,true))}" target="_blank" rel="noopener">${icon('map')} Chỉ đường bằng Google Maps ${icon('external')}</a>${b.status==='pending'?`<p class="notice">${h.name} sẽ xác nhận sớm. Bác sẽ nhận được thông báo ngay khi có phản hồi.</p>`:''}${b.status==='accepted'?`<div class="safe-note">${icon('shield')} Khi gặp, bác đối chiếu tên và ảnh của ${h.name} trên An Vui. Bác có thể rủ người thân đi cùng. Chỉ bấm “Đã học xong” khi bác tự làm được.</div><button class="primary wide" data-action="finish-support">${icon('check')} Đã học xong</button>`:''}${['pending','accepted'].includes(b.status)?'<button class="secondary wide" data-action="cancel-support">Hủy lịch hẹn</button>':''}${b.status==='finished'?`<div class="notice">Buổi hướng dẫn đã hoàn thành. Bác thanh toán ${vnd(b.price)} cho ${h.name} bằng tiền mặt hoặc chuyển khoản. Cảm ơn bác đã tin tưởng An Vui!</div>`:''}`}
function supportRequests(){if(state.role!=='helper')return nearby();const b=state.support;return `<button class="back-btn" data-screen="home">${icon('back')} Trang chủ</button><h1 class="screen-title">Yêu cầu hướng dẫn</h1><p class="screen-subtitle">Các bác ở gần đang cần bạn chỉ tận tay.</p>${!b||b.status==='cancelled'?'<div class="empty">Chưa có yêu cầu mới.<br>Bạn sẽ nhận thông báo khi có bác ở gần cần giúp.</div>':`<article class="community-post">${person('Bác Minh','M','68 tuổi · Cầu Giấy · cách bạn 0,8 km')}<h2 class="card-title">${esc(b.issue)}</h2><p>${esc(b.place)}<br>${esc(b.slot)}</p><div class="stat-row"><span>Chi phí buổi học</span><strong>${vnd(b.price)}</strong></div><div class="stat-row"><span>Phí nền tảng (20%)</span><strong>${vnd(b.price*.2)}</strong></div><div class="stat-row"><span>Bạn nhận</span><strong>${vnd(b.price*.8)}</strong></div>${b.status==='pending'?'<button class="primary wide" data-action="accept-support">Nhận lịch này</button>':`<div class="notice">${b.status==='accepted'?'Đã nhận lịch. Nhớ nhắn bác Minh trước buổi hẹn nhé.':'Bác Minh đã xác nhận học xong. Thu nhập sẽ được chuyển vào ví của bạn.'}</div>`}</article>`}<div class="safe-note">${icon('shield')} Không hỏi mật khẩu, mã OTP, không mở ứng dụng ngân hàng và không cầm điện thoại của bác đi nơi khác.</div>`}
function serviceRevenue(){return `<section class="service-business"><div><div class="eyebrow">NGUỒN THU MỚI · HƯỚNG DẪN TRỰC TIẾP</div><h2>Chỉ tận tay, trả phí theo buổi.</h2><p>Hỏi đáp online tiếp tục miễn phí. Khi cần gặp trực tiếp, cô bác hoặc con cháu đặt buổi hướng dẫn với giá và điểm hẹn được chốt trước.</p><button class="primary" data-action="campaign-demo">Thử đặt người hướng dẫn ${icon('arrow')}</button></div><div class="service-unit"><div class="stat-row"><span>Một buổi 45 phút</span><strong>99.000đ</strong></div><div class="stat-row"><span>Người hỗ trợ nhận 80%</span><strong>79.200đ</strong></div><div class="stat-row"><span>Doanh thu nền tảng 20%</span><strong>19.800đ</strong></div><p>Giả định chi phí biến đổi 7.000đ/buổi → còn 12.800đ đóng góp trước chi phí cố định và thuế. Đây là giả định để thử nghiệm. Nguồn thu này chưa cộng vào bảng tính ba nguồn bên dưới.</p></div></section>`}
function campaign(){return `<section class="campaign-page"><div class="campaign-intro"><div><div class="eyebrow">CHIẾN DỊCH AN VUI · Ý TƯỞNG THỬ NGHIỆM</div><h1>Để ba mẹ<br>không <em>ngại hỏi.</em></h1><p>Con chỉ qua điện thoại, ba mẹ vẫn chưa tìm thấy nút.<br>Thêm một lời chỉ tận tay, bớt một lần cả nhà khó xử.</p><div class="campaign-actions"><button class="primary" data-action="campaign-demo">Xem cách đặt người hướng dẫn ${icon('arrow')}</button><a class="secondary" href="assets/campaign-story.jpg" download="An-Vui-De-ba-me-khong-ngai-hoi.jpg">${icon('download')} Tải ảnh kể chuyện</a></div><div class="campaign-tone">Chỉ tận tay. Hiểu từng bước.<br><span>Giúp ba mẹ tự tin, để những cuộc gọi lại là niềm vui.</span></div></div><figure class="campaign-poster"><img src="assets/campaign-story.webp" alt="Quảng cáo kể chuyện: mẹ gọi con nhờ chỉ điện thoại, con đang bận và mất kiên nhẫn; mẹ tự hỏi trên An Vui, tìm người hỗ trợ gần mình; bạn trẻ kiên nhẫn hướng dẫn tại điểm hẹn để mẹ tự gọi video cho con."><figcaption>Ảnh quảng cáo bằng AI · Nhân vật hư cấu · Dịch vụ đề xuất</figcaption></figure></div><div class="campaign-storyline"><article><span>01 · CHUYỆN NHIỀU NHÀ</span><h2>“Con ơi, mẹ bấm chỗ nào?”</h2><p>Con nói “góc phải”, mẹ nhìn thấy nhiều nút. Con sốt ruột. Mẹ lặng đi: “Thôi, để mẹ tự mò.”</p></article><article><span>02 · MỘT CÁCH HỎI KHÁC</span><h2>“Bác hỏi ở đây nhé.”</h2><p>Đặt câu hỏi trên An Vui. Nếu online chưa đủ, chọn người hỗ trợ quanh mình và hẹn nơi thuận tiện.</p></article><article><span>03 · BA MẸ TỰ LÀM ĐƯỢC</span><h2>“Lần này, mẹ tự gọi rồi!”</h2><p>Người trẻ chỉ từng bước; ba mẹ tự bấm trên máy của mình. Cuộc gọi sau có thêm một nụ cười.</p></article></div><section class="campaign-keyvisual"><img src="assets/campaign-keyvisual.webp" alt="Người mẹ tự tin tự dùng điện thoại bên cạnh một bạn trẻ hướng dẫn tận tình tại điểm sinh hoạt cộng đồng" loading="lazy"><div><div class="eyebrow">LỜI HỨA DỊCH VỤ</div><h2>Có người ở gần.<br>Có lời chỉ tận tay.</h2><p>Hỗ trợ gọi video, gửi ảnh, chỉnh cỡ chữ và những việc điện thoại hằng ngày. Để ba mẹ hiểu và tự thực hiện.</p><button class="primary" data-action="campaign-demo">Cùng ba mẹ dùng thử An Vui ${icon('arrow')}</button><small>Dự kiến thử nghiệm đầu tiên tại Hà Nội.</small></div></section><div class="strategy-columns"><article class="strategy-section"><h2>Quảng cáo dẫn đến hành động nào?</h2><ol><li><strong>Người con nhận ra tình huống quen.</strong> Video ngắn 30 giây và ảnh kể chuyện, không gán nhãn con bất hiếu hay ba mẹ kém cỏi.</li><li><strong>Mở đúng việc ba mẹ cần.</strong> Landing page dẫn thẳng đến đặt câu hỏi hoặc “Có người chỉ tận tay”.</li><li><strong>Cùng ba mẹ hoàn thành bước đầu.</strong> Chọn việc cần giúp, khu vực, người hướng dẫn và điểm hẹn.</li><li><strong>Đo buổi hoàn tất.</strong> Tách người quan tâm, yêu cầu hợp lệ và buổi có xác nhận; không lấy lượt thích làm bằng chứng kinh doanh.</li></ol></article><article class="strategy-section"><h2>Chạy thử ở một khu vực nhỏ</h2><p><strong>Tệp chính:</strong> con cháu trưởng thành có ba mẹ dùng điện thoại, sống hoặc làm việc xa nhau. Thông điệp phụ cho cô bác: “Cứ hỏi nhé, có người chỉ từng bước.”</p><p><strong>Kênh:</strong> video ngắn trên Facebook, TikTok; ảnh trong nhóm cộng đồng được quản trị viên cho phép; buổi hướng dẫn tại câu lạc bộ người cao tuổi.</p><p><strong>Giả định ngân sách truyền thông:</strong> 3 triệu / 14 ngày: 1,8 triệu thử tiếp cận mới, 600.000đ phân phối nội dung người đã quan tâm, 600.000đ vật liệu và hoạt động địa bàn. Chưa gồm nhân sự, quà tặng hay trợ giá.</p></article></div>${serviceRevenue()}<section class="strategy-section"><h2>Kịch bản phim 30 giây</h2><table class="metric-table"><thead><tr><th>Thời gian</th><th>Hình & lời thoại</th><th>Mục đích</th></tr></thead><tbody><tr><td>0–8 giây</td><td>Mẹ: “Con ơi, mẹ bấm chỗ nào?” Con vừa làm vừa đáp: “Mẹ bấm như con vừa nói đi!”</td><td>Nhận ra tình huống, thấy cả hai đang khó</td></tr><tr><td>8–12 giây</td><td>Mẹ nhìn máy: “Thôi, để mẹ tự mò vậy.” Con khựng lại.</td><td>Khoảng lặng, không đổ lỗi</td></tr><tr><td>12–20 giây</td><td>Mẹ đặt câu hỏi An Vui, chọn người hỗ trợ và điểm hẹn. Người trẻ: “Bác cứ bấm thử, cháu chỉ từng bước.”</td><td>Giải thích dịch vụ qua thao tác</td></tr><tr><td>20–26 giây</td><td>Mẹ tự gọi video: “Lần này mẹ tự gọi được rồi!” Con mỉm cười: “Mẹ giỏi quá!”</td><td>Trả lại sự chủ động cho ba mẹ</td></tr><tr><td>26–30 giây</td><td>An Vui. Chỉ tận tay. Hiểu từng bước. Cùng ba mẹ dùng thử.</td><td>Một lời kêu gọi rõ ràng</td></tr></tbody></table></section><div class="campaign-copy"><h2>Bài đăng gợi ý</h2><p>“Mẹ bấm như con vừa nói đi!”<br>Có khi mình đã nói câu ấy trong một ngày quá bận.<br>Nhưng phía bên kia, mẹ chỉ đang chưa tìm thấy nút cần bấm.</p><p>Với An Vui, ba mẹ có thể đặt câu hỏi, chọn người hướng dẫn ở gần và được chỉ từng bước trên chính điện thoại của mình.</p><p><strong>Để ba mẹ không ngại hỏi.<br>Chỉ tận tay. Hiểu từng bước.</strong></p><p>Cùng ba mẹ dùng thử An Vui. Dịch vụ trực tiếp đang ở giai đoạn ý tưởng, chưa nhận lịch hẹn thật.</p><button class="secondary" data-action="copy-campaign">${icon('copy')} Sao chép nội dung</button></div><div class="sources">Bản đồ trong app là sơ đồ minh họa. Nút Google Maps mở dịch vụ Google theo khu vực/điểm hẹn do người dùng chọn, theo <a href="https://developers.google.com/maps/documentation/urls/get-started" target="_blank" rel="noopener">tài liệu Maps URLs</a>. Không có danh sách người hỗ trợ trực tiếp theo thời gian thực. Bộ ảnh và số liệu quảng cáo là đề xuất, chưa phải chiến dịch đã chạy.</div></section>`}
const featureActions={
 'campaign-demo'(){state.role='senior';screenTo('nearby');window.scrollTo({top:0,behavior:'smooth'})},
 'locate-support'(){if(!navigator.geolocation){toast('Máy chưa hỗ trợ định vị. Bác nhập điểm hẹn bên dưới nhé.');return}locating=true;renderScreen();navigator.geolocation.getCurrentPosition(pos=>{livePosition={latitude:pos.coords.latitude,longitude:pos.coords.longitude};locating=false;if(state.screen==='nearby')renderScreen();toast('Đã xác định vị trí của bác.');},()=>{locating=false;if(state.screen==='nearby')renderScreen();toast('Chưa lấy được vị trí. Bác nhập địa điểm hẹn bên dưới nhé.');},{enableHighAccuracy:false,timeout:10000,maximumAge:60000})},
 'accept-support'(){if(state.role!=='helper'||!state.support||state.support.status!=='pending')return;state.support.status='accepted';persist();renderScreen();toast('Đã nhận lịch hẹn với bác Minh.')},
 'finish-support'(){if(state.role!=='senior'||state.support?.status!=='accepted')return;state.support.status='finished';persist();renderScreen();toast('Cảm ơn bác! Hẹn gặp lại bác ở buổi sau.')},
 'cancel-support'(){if(state.role!=='senior'||!['pending','accepted'].includes(state.support?.status))return;state.support.status='cancelled';persist();renderScreen();toast('Đã hủy lịch hẹn.')},
 async 'copy-campaign'(){const t='“Mẹ bấm như con vừa nói đi!”\nCó khi mình đã nói câu ấy trong một ngày quá bận.\nNhưng phía bên kia, mẹ chỉ đang chưa tìm thấy nút cần bấm.\n\nVới An Vui, ba mẹ có thể đặt câu hỏi, chọn người hướng dẫn ở gần và được chỉ từng bước trên chính điện thoại của mình.\n\nĐể ba mẹ không ngại hỏi.\nChỉ tận tay. Hiểu từng bước.\n\nCùng ba mẹ dùng thử An Vui. Dịch vụ trực tiếp đang ở giai đoạn ý tưởng, chưa nhận lịch hẹn thật.';try{await navigator.clipboard.writeText(t);toast('Đã sao chép bài đăng')}catch{toast('Bác chọn nội dung trên trang để sao chép nhé.')}}
};
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.supportHelper){if(state.role!=='senior')return;state.helperId=el.dataset.supportHelper;screenTo('helper-detail')}if(el.dataset.supportIssue){state.supportIssue=el.dataset.supportIssue;persist();renderScreen()}});
document.addEventListener('input',e=>{if(e.target.id==='support-area'){state.supportLandmark=e.target.value;persist();const link=document.querySelector('#support-map-link');if(link)link.href=mapsURL(e.target.value||'Hồ Hoàn Kiếm, Hà Nội')}});
document.addEventListener('submit',e=>{if(e.target.id!=='support-booking-form')return;e.preventDefault();if(state.role!=='senior')return;const data=new FormData(e.target);if(!data.get('consent')){toast('Bác tích vào ô đồng ý chia sẻ điểm hẹn trước nhé.');return}const place=String(data.get('place')||'').trim();if(place.length<5){toast('Bác ghi rõ điểm hẹn hơn một chút nhé.');return}if(state.support&&['pending','accepted'].includes(state.support.status)){toast('Bác đã có một yêu cầu đang chờ. Hoàn thành hoặc hủy lịch đó trước nhé.');return}state.support={helperId:state.helperId||'minhanh',issue:String(data.get('issue')),place,slot:String(data.get('slot')),price:sessionPrice,status:'pending'};state.supportLandmark=place;persist();screenTo('appointment');toast(`Đã gửi yêu cầu cho ${(nearbyHelpers.find(h=>h.id===state.support.helperId)||nearbyHelpers[0]).name}. Bác sẽ nhận thông báo khi có xác nhận.`)});
